class HomeBannerAd extends StatefulWidget {
const HomeBannerAd({super.key});

@override
State<HomeBannerAd> createState() => _HomeBannerAdState();
}

class _HomeBannerAdState extends State<HomeBannerAd> {
BannerAd? _bannerAd;
bool _isLoaded = false;

// ID de prueba de Google.
// Sustituir por el ID real cuando la aplicación esté lista.
static const String _testAdUnitId =
'ca-app-pub-3940256099942544/6300978111';

void _loadBanner() {
final banner = BannerAd(
adUnitId: _testAdUnitId,
size: AdSize.banner,
request: const AdRequest(),
listener: BannerAdListener(
onAdLoaded: (ad) {
if (!mounted) {
ad.dispose();
return;
}

setState(() {
_bannerAd = ad as BannerAd;
_isLoaded = true;
});
},
onAdFailedToLoad: (ad, error) {
ad.dispose();
},
),
);

banner.load();
}

@override
void initState() {
super.initState();
_loadBanner();
}

@override
void dispose() {
_bannerAd?.dispose();
super.dispose();
}

@override
Widget build(BuildContext context) {
if (!_isLoaded || _bannerAd == null) {
return const SizedBox.shrink();
}

return Container(
alignment: Alignment.center,
width: double.infinity,
height: _bannerAd!.size.height.toDouble(),
child: AdWidget(ad: _bannerAd!),
);
}
}
